pub fn emit_movabs(buf: &mut Vec<u8>, output: PhysReg, rel: i64) {
  let base = buf.len();
  match output {
    PhysReg::R10 => {
      buf.extend_from_slice(&[0x49, 0xBA, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::R11 => {
      buf.extend_from_slice(&[0x49, 0xBB, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::R12 => {
      buf.extend_from_slice(&[0x49, 0xBC, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::R13 => {
      buf.extend_from_slice(&[0x49, 0xBD, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::R14 => {
      buf.extend_from_slice(&[0x49, 0xBE, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::R15 => {
      buf.extend_from_slice(&[0x49, 0xBF, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::R8 => {
      buf.extend_from_slice(&[0x49, 0xB8, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::R9 => {
      buf.extend_from_slice(&[0x49, 0xB9, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::Rax => {
      buf.extend_from_slice(&[0x48, 0xB8, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::Rbp => {
      buf.extend_from_slice(&[0x48, 0xBD, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::Rbx => {
      buf.extend_from_slice(&[0x48, 0xBB, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::Rcx => {
      buf.extend_from_slice(&[0x48, 0xB9, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::Rdi => {
      buf.extend_from_slice(&[0x48, 0xBF, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::Rdx => {
      buf.extend_from_slice(&[0x48, 0xBA, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    PhysReg::Rsi => {
      buf.extend_from_slice(&[0x48, 0xBE, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00])
    }
    _ => unreachable!(),
  }
  let bytes = rel.to_le_bytes();
  buf[base + 2..base + 2 + 8].copy_from_slice(&bytes);
}

