pub fn emit_ret(buf: &mut Vec<u8>) {
  buf.extend_from_slice(&[0xC3]);
}

pub fn emit_jmp_rel32(buf: &mut Vec<u8>, rel: i32) {
  let base = buf.len();
  buf.extend_from_slice(&[0xE9, 0x00, 0x00, 0x00, 0x00]);
  let bytes = rel.to_le_bytes();
  buf[base + 1..base + 1 + 4].copy_from_slice(&bytes);
}

pub fn emit_je_rel32(buf: &mut Vec<u8>, rel: i32) {
  let base = buf.len();
  buf.extend_from_slice(&[0x0F, 0x84, 0x00, 0x00, 0x00, 0x00]);
  let bytes = rel.to_le_bytes();
  buf[base + 2..base + 2 + 4].copy_from_slice(&bytes);
}

